"""Owned headless CLI adapter. Every native attempt is saved before sending; no retry."""
import json,os,subprocess,time
from pathlib import Path
root=Path(__file__).resolve().parent
def check_raw_budget():
    observed=sum(p.stat().st_size for phase in ('stock-app-01',)
                 for p in (root/phase).rglob('*') if p.is_file())
    if observed>128*1024*1024:raise RuntimeError('STOP: observed comparison raw exceeds 128MiB')
    return observed
class Browser:
    def __init__(self,directory,namespace,session,control,job):
        self.job=job;self.directory=Path(directory);self.directory.mkdir(exist_ok=False)
        self.namespace=namespace;self.session=session;self.control=control;self.sequence=0
        self.ever_opened=False
    def call(self,*args):
        if args[0] not in ('close','session'):check_raw_budget()
        self.sequence+=1;out=self.directory/f'{self.sequence:03d}';out.mkdir()
        exe=root.parent/'deps/node_modules/agent-browser/bin/agent-browser-win32-x64.exe'
        command=[str(exe),'--config',str(root.parent/'agent-browser.json'),'--namespace',self.namespace,
                 '--session',self.session,'--headed','false','--no-webmcp','--engine','chrome',
                 '--executable-path',r'C:\Program Files\Google\Chrome\Application\chrome.exe',
                 '--args','--disable-gpu','--idle-timeout','15m','--json',*args]
        (out/'COMMAND_PRIVATE.json').write_text(json.dumps(command)+'\n',encoding='utf-8')
        result={'started_ns':time.perf_counter_ns(),'operation':args[0],'actual_child_exit_code':None,'outcome':'UNKNOWN'}
        child=None
        try:
            with (out/'stdout.private.bin').open('xb') as stdout,(out/'stderr.private.bin').open('xb') as stderr:
                child=self.job.launch(command,cwd=root,env={k:v for k,v in os.environ.items()
                    if not k.startswith(('AGENT_BROWSER_','AI_GATEWAY_'))},stdout=stdout,stderr=stderr)
                result['pid']=child.pid
                (out/'SPAWN.json').write_text(json.dumps(result)+'\n',encoding='utf-8')
                try:child.wait(2 if args==('wait','--fn','false') else 40)
                except TimeoutError:
                    result['observation_timeout']=True
                    child.terminate();child.wait(5)
            result['actual_child_exit_code']=child.poll()
            if result.get('observation_timeout'):raise RuntimeError('STOP: native observation timeout; daemon effect unknown')
            if child.poll()!=0:raise RuntimeError('STOP: native command failed')
            raw=(out/'stdout.private.bin').read_bytes()
            if len(raw)>2*1024*1024:raise RuntimeError('STOP: response exceeds prospective observation bound')
            response=json.loads(raw)
            if response.get('success') is not True:raise RuntimeError('STOP: browser command unsuccessful')
            life=response.get('data',{}).get('lifecycle')
            if life:
                if life.get('relaunchedBrowser') or life.get('restartedBackground'):
                    raise RuntimeError('STOP: unexpected generation change')
                if self.ever_opened and life.get('launched'):
                    raise RuntimeError('STOP: unexpected new browser')
            if args[0]=='open':self.ever_opened=True
            if args[0] not in ('close','session'):check_raw_budget()
            result['outcome']='RETURNED'
            return response['data']
        except BaseException as e:
            result['error']={'type':type(e).__name__,'message':str(e)}
            raise
        finally:
            result['ended_ns']=time.perf_counter_ns()
            if child is not None:result['actual_child_exit_code']=child.poll()
            (out/'RESULT.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8')

class Editor:
    def __init__(self,browser,filename):self.browser=browser;self.filename=filename;self.replacements=0;self.saves=0
