        self.browser.call('wait','--fn',check)
        self.browser.call('press','Escape')
    def snapshot_editor(self):
        data=self.browser.call('snapshot')
        expected=self.browser.control['origin']+'/lab/tree/'+self.filename
        if not data.get('origin','').startswith(self.browser.control['origin']+'/lab'):raise RuntimeError('STOP: wrong owned application origin')
        refs=[key for key,value in data.get('refs',{}).items() if value.get('role')=='textbox']
