        selected='- tab "'+self.filename+'" [selected,'
        if selected not in data.get('snapshot',''):raise RuntimeError('STOP: document tab not selected')
        return '@'+refs[0]
    def read_current(self):
        ref=self.snapshot_editor()
        data=self.browser.call('get','text',ref)
        if not data.get('origin','').startswith(self.browser.control['origin']+'/lab'):
