        text=data['text']
        # Declared stock CodeMirror rendering: LF lines plus exactly one drawn trailing newline.
        if not text.endswith('\n') or '\r' in text:raise RuntimeError('STOP: unsupported editor text representation')
        return text[:-1].replace('\n','\r\n')
    def replace_once(self,text):
