    def save_once(self):
        if self.saves or self.replacements!=1:raise RuntimeError('STOP: invalid save count')
        ref=self.snapshot_editor()
        selected="document.querySelectorAll('.lm-DockPanel-tabBar .lm-TabBar-tab.lm-mod-current')"
        # Public tab DOM only. Dirty must be present before the sole Save and absent afterward.
        self.browser.call('wait','--fn',f"{selected}.length === 1 && {selected}[0].classList.contains('jp-mod-dirty')")
        self.browser.call('click',ref)
        self.saves+=1
        self.browser.call('press','Control+s')
        self.browser.call('wait','--fn',f"{selected}.length === 1 && !{selected}[0].classList.contains('jp-mod-dirty')")
        self.snapshot_editor()

