"""New ordinary V4/shared-caller stock GUI coupling, deterministic subject only."""
import hashlib, importlib.util, json, sys, time, urllib.request
from pathlib import Path
root=Path(__file__).resolve().parent
sys.path.insert(0,str(root))
from winjob import Job
import caller_source as caller
from finite_role_recovery import run_with_one_recovery
phase=root/'stock-app-01'; output=root/'qualification-01'; output.mkdir()
sources=[p for p in root.rglob('*') if p.is_file() and output not in p.parents and '__pycache__' not in p.parts and p.name not in ('stdout.txt','stderr.txt','guard.stdout.txt','guard.stderr.txt')]
pins={str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sources}
(output/'SOURCE_BEFORE.json').write_text(json.dumps(pins,indent=2))
spec=importlib.util.spec_from_file_location('editor',root/'browser-editor.py')
module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
job=Job(); launcher=browser=control=None
report={'outcome':'STOP','model_calls':0,'subject_results':[],'formal_replay':0,'cases':[]}
stdout=(output/'launcher.stdout.private.bin').open('xb');stderr=(output/'launcher.stderr.private.bin').open('xb')
events=[]
try:
    argv=[str(root.parent.parent/'jupyterlab-5442/env/Scripts/python.exe'),str(root/'launch-app.py'),'stock-app-01','--ttl-seconds','300']
    launcher=job.launch(argv,root,stdout,stderr)
    deadline=time.monotonic()+60
    while not (phase/'START_PUBLIC.json').exists():
        if launcher.poll() is not None:raise RuntimeError('launcher ended before readiness')
        if time.monotonic()>deadline:raise RuntimeError('readiness unknown; no restart')
        time.sleep(.1)
    control=json.loads((phase/'CONTROL_PRIVATE.json').read_text())
    browser=module.Browser(phase/'browser','2d0b-joint-semantic-stock-01','2d0b-joint-semantic-stock-session-01',control,job)
    tasks=json.loads((root/'TASKS_CONTROLLER.json').read_text(encoding='utf-8'))
    for fixture in tasks:
        editor=module.Editor(browser,fixture['filename']);editor.open();editor.assert_autosave_off()
        receipts=[];invocations=[];package_events=[];caller_events=[];errors=[]
        # Returned methods are known completions, not all attempted native inputs.
        class Adapter:
            @property
            def replacements(self):return editor.replacements
            @property
            def saves(self):return editor.saves
            def read_current(self):return editor.read_current()
            def replace_once(self,text):
                editor.replace_once(text);receipts.append('replacement_returned')
            def save_once(self):
                editor.save_once();receipts.append('save_returned')
        adapter=Adapter()
        task={k:fixture[k] for k in ('id','document','old_person','new_person')}
        expected=(root/'EXPECTED_SCORER_PRIVATE.txt').read_bytes()
        def subject(t,document):
            if report['model_calls']:raise RuntimeError('STOP: second actual subject call forbidden')
            report['model_calls']+=1
            import subject
            actual=subject.attempt(root/'subject-attempt-01',{**t,'request':fixture['request']},document)
            report['subject_results'].append(actual)
            return actual['output']
        def record(name,data):
            package_events.append({'event':name,'data':data})
            if fixture['id']=='late-journal' and name=='save_returned':raise OSError('own ordinary post-save journal injection')
        def execute(payload):
            invocations.append('execute')
            try:
                run_with_one_recovery(task,adapter,subject,record)
                return {'status':'completed'}
            except (OSError,RuntimeError) as error:
                errors.append({'type':type(error).__name__,'message':str(error)})
                # replacement count is advanced BEFORE any controller input.
                return {'status':'safe_yield','reason':'execution_failed','completed_actions':len(receipts),'input_dispatched':bool(editor.replacements or editor.saves)}
        def verify(payload):
            invocations.append('verify_effect')
            good=(phase/'files'/fixture['filename']).read_bytes()==expected and (phase/'files/sibling.txt').read_bytes()==b'caller-stock-v4 sibling\r\n'
            return {'status':'succeeded' if good else 'failed'}
        selected={'filename':fixture['filename']}
        def revalidate(payload):
            editor.snapshot_editor()
            return {'status':'revalidated'}
        config=dict(target=fixture['filename'],route='reuse',coarse_origin='caller_provided',provided_coarse=None,cached_target=selected,local_repair_on=[],repair_on=[],session_id='stock-v4-'+fixture['id'])
        result=caller.run(config,{'reuse_revalidate':revalidate,'final_revalidate':revalidate,'execute':execute,'verify_effect':verify,'journal':lambda e:caller_events.append(e)})
        target=(phase/'files'/fixture['filename']).read_bytes()
        sibling=(phase/'files/sibling.txt').read_bytes()
        row={'id':fixture['id'],'result':result,'invocations':invocations,'completed_receipts':receipts,'errors':errors,'package_events':package_events,'caller_events':caller_events,'replacements':editor.replacements,'saves':editor.saves,'target_hex':target.hex(),'sibling_hex':sibling.hex(),'post_yield_effect_present':target==expected and sibling==b'caller-stock-v4 sibling\r\n'}
        report['cases'].append(row)
        assert row['post_yield_effect_present'] and editor.replacements==editor.saves==1
        if fixture['id']=='healthy':assert result['outcome']=='TASK_SUCCEEDED' and invocations==['execute','verify_effect']
        else:
            assert result['outcome']=='EXECUTION_INCOMPLETE' and invocations==['execute']
            assert result['execution_progress']['completed_actions']==2
    report['live_job']=job.snapshot()
    report['outcome']='ACTUAL_SEMANTIC_STOCK_EFFECT_VERIFIED'
except BaseException as error:
    report['error']={'type':type(error).__name__,'message':str(error)}
finally:
    if browser:
        try:browser.call('close');report['browser_close_returned']=True
        except BaseException as error:report['browser_close_error']=str(error)
    if control:
        try:
            req=urllib.request.Request(control['origin']+'/api/shutdown',data=b'',method='POST',headers={'Authorization':'token '+control['token']})
            with urllib.request.urlopen(req,timeout=5) as response:report['shutdown_status']=response.status;response.read()
        except BaseException as error:report['shutdown_error']=str(error)
    if launcher:
        try:report['launcher_actual_exit']=launcher.wait(15)
        except TimeoutError:report['launcher_actual_exit']=None
    try:report['release']=job.finish(2,5)
    except BaseException as error:report['release_error']=str(error)
    job.close();stdout.close();stderr.close()
    report['source_unchanged']=all(hashlib.sha256((root/path).read_bytes()).hexdigest()==pin for path,pin in pins.items())
    report['native_attempts']=browser.sequence if browser else 0
    (output/'RESULT.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({k:v for k,v in report.items() if k!='cases'}))
passed=report['outcome']=='ACTUAL_SEMANTIC_STOCK_EFFECT_VERIFIED' and report.get('launcher_actual_exit')==0 and report.get('release',{}).get('job_members_released') and not report.get('release',{}).get('forced_job_termination') and report['source_unchanged']
sys.exit(0 if passed else 1)

